cssCode:
.apple-wrap { height: 200vh; width: 100%; background: green; }
.apple-sticky {
  position: sticky; top: 0; height: 100vh; width: 100%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  overflow: hidden;
}
.apple-device {
  font-size: 80px;
  transform: scale(0.5) translateY(100px);
  opacity: 0;
  transition: transform 0.1s linear, opacity 0.1s linear;
}
.apple-text {
  color: white; font-family: sans-serif; font-size: 24px; font-weight: bold;
  margin-top: 20px; opacity: 0; transition: opacity 0.1s linear;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:green;';

const wrap = document.createElement('div');
wrap.className = 'apple-wrap';

const sticky = document.createElement('div');
sticky.className = 'apple-sticky';

const device = document.createElement('div');
device.className = 'apple-device';
device.innerText = '📱';

const text = document.createElement('div');
text.className = 'apple-text';
text.innerText = 'PRO VISION';

sticky.appendChild(device);
sticky.appendChild(text);
wrap.appendChild(sticky);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const maxScroll = c.scrollHeight - c.clientHeight;
  const progress = Math.min(c.scrollTop / maxScroll, 1);

  // Apple style scaling and revealing
  const scale = 0.5 + (progress * 1.5);
  const yPos = 100 - (progress * 100);
  const opacity = progress * 2;

  device.style.transform = `scale(${scale}) translateY(${yPos}px)`;
  device.style.opacity = opacity;
  text.style.opacity = progress > 0.5 ? (progress - 0.5) * 2 : 0;
});
